import{_ as a,o as t,c as i,a7 as s}from"./chunks/framework.CWfAgRyf.js";const g=JSON.parse('{"title":"Migrating from PocketMine-MP (PMMP)","description":"How to switch an existing PocketMine-MP (PMMP) server to Axolotl-PM, an actively maintained fork of PMMP. Covers plugin compatibility, worlds, configuration and the upgrade steps.","frontmatter":{"title":"Migrating from PocketMine-MP (PMMP)","outline":"deep","description":"How to switch an existing PocketMine-MP (PMMP) server to Axolotl-PM, an actively maintained fork of PMMP. Covers plugin compatibility, worlds, configuration and the upgrade steps.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/migrating-from-pocketmine-mp"}]]},"headers":[],"relativePath":"docs/migrating-from-pocketmine-mp.md","filePath":"docs/migrating-from-pocketmine-mp.md","lastUpdated":null}'),o={name:"docs/migrating-from-pocketmine-mp.md"};function n(r,e,l,c,p,d){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="migrating-from-pocketmine-mp-pmmp" tabindex="-1">Migrating from PocketMine-MP (PMMP) <a class="header-anchor" href="#migrating-from-pocketmine-mp-pmmp" aria-label="Permalink to &quot;Migrating from PocketMine-MP (PMMP)&quot;">​</a></h1><p>PocketMine-MP (PMMP) is no longer maintained. The <a href="https://github.com/pmmp/PocketMine-MP" target="_blank" rel="noreferrer">pmmp/PocketMine-MP</a> repository was archived in July 2026, and its last release was 5.44.3.</p><p>Axolotl-PM is an actively maintained fork of PMMP. It continues from the last PMMP code and follows PMMP’s <a href="/website/previews/pr-1/native-9f14c22779bf/docs/developers/plugin-docs/api-version-spec">versioning policy</a>, starting at 5.45.0.</p><p>Most PMMP servers can switch to Axolotl-PM without changing their plugins, worlds or configuration.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><h3 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h3><p>PMMP plugins are compatible with Axolotl-PM unless they use the network API.</p><p>Axolotl-PM keeps the <code>pocketmine\\</code> namespaces, and the plugin loader and <code>plugin.yml</code> format are the same as in PMMP. The API version is the server version, so a plugin that declares <code>api: 5.0.0</code> loads on Axolotl-PM 5.x.</p><p>A plugin may need an update if it:</p><ul><li>creates or reads packets directly using the classes in <code>pocketmine\\network\\mcpe\\protocol</code></li><li>uses other network internals under <code>pocketmine\\network\\mcpe</code>, such as the <code>cache</code>, <code>convert</code> or <code>handler</code> namespaces</li><li>sets <code>mcpe-protocol</code> in its <code>plugin.yml</code>, since Axolotl-PM uses a newer protocol version than PMMP</li><li>registers its own network interface with <code>Network::registerInterface()</code>, which is deprecated in favour of the new transport API</li></ul><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>If a plugin fails to load, see <a href="/website/previews/pr-1/native-9f14c22779bf/docs/faq/plugins/incompatibleapi">What does “Incompatible API version” mean when loading a plugin?</a>.</p></div><h3 id="worlds-and-server-data" tabindex="-1">Worlds and server data <a class="header-anchor" href="#worlds-and-server-data" aria-label="Permalink to &quot;Worlds and server data&quot;">​</a></h3><p>Axolotl-PM uses the same world format and the same data folder layout as PMMP. Your <code>worlds</code>, <code>players</code>, <code>plugin_data</code> and <code>resource_packs</code> folders, and files like <code>ops.txt</code> and <code>banned-players.txt</code>, work without conversion.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p><code>server.properties</code> and <code>pocketmine.yml</code> work as they are. No settings were removed, and the only new section is <code>transport</code> for <a href="#nethernet">NetherNet</a>.</p><p>Axolotl-PM uses its own servers for crash reports, update checks and timings reports. New servers get these settings automatically, but an existing <code>pocketmine.yml</code> keeps the PMMP addresses. Change these three <code>host</code> settings in your <code>pocketmine.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto-report</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">crash.axolotl-pm.org</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto-updater</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">update.axolotl-pm.org</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">timings</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">timings.axolotl-pm.org</span></span></code></pre></div><p>Only change the <code>host</code> lines; leave the other settings in each section as they are.</p><h3 id="nethernet" tabindex="-1">NetherNet <a class="header-anchor" href="#nethernet" aria-label="Permalink to &quot;NetherNet&quot;">​</a></h3><p>Axolotl-PM supports <a href="/website/previews/pr-1/native-9f14c22779bf/docs/installation/nethernet-usage">NetherNet</a>, the WebRTC-based transport that replaces RakNet in Minecraft: Bedrock Edition. PMMP only supports RakNet.</p><p>An existing <code>pocketmine.yml</code> has no <code>transport</code> section, so Axolotl-PM keeps using RakNet after you switch. To use NetherNet, add this to your <code>pocketmine.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">transport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nethernet</span></span></code></pre></div><p>See <a href="/website/previews/pr-1/native-9f14c22779bf/docs/installation/nethernet-usage">NetherNet Usage</a> for the other settings and for setting up TLS.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>NetherNet doesn’t use the same ports as RakNet. It needs TCP port <code>19132</code> for signaling and UDP ports for game traffic. Update your firewall and port forwarding before you switch; see <a href="/website/previews/pr-1/native-9f14c22779bf/docs/installation/nethernet-usage#ports-you-need-to-open">Ports you need to open</a>.</p></div><h3 id="php" tabindex="-1">PHP <a class="header-anchor" href="#php" aria-label="Permalink to &quot;PHP&quot;">​</a></h3><p>Axolotl-PM requires PHP 8.1 or newer, the same as PMMP 5. It also needs the <code>webrtc</code> PHP extension for NetherNet, which PMMP’s PHP binaries don’t include.</p><p>Use the PHP binaries from <a href="https://github.com/axolotl-pm/PHP-Binaries/releases" target="_blank" rel="noreferrer">axolotl-pm/PHP-Binaries</a>, which include it. The official installer downloads them for you.</p><h2 id="switching-to-axolotl-pm" tabindex="-1">Switching to Axolotl-PM <a class="header-anchor" href="#switching-to-axolotl-pm" aria-label="Permalink to &quot;Switching to Axolotl-PM&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Stop your server and back up the whole server folder before you start.</p></div><h3 id="using-the-official-installer-linux-macos-only" tabindex="-1">Using the official installer (Linux/MacOS only) <a class="header-anchor" href="#using-the-official-installer-linux-macos-only" aria-label="Permalink to &quot;Using the official installer (Linux/MacOS only)&quot;">​</a></h3><p><code>cd</code> into your existing server folder and run the <a href="/website/previews/pr-1/native-9f14c22779bf/docs/installation/get-dot-axolotl-pm-dot-org">official installer</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://get.axolotl-pm.org</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre></div><p>The installer replaces <code>PocketMine-MP.phar</code>, <code>start.sh</code> and the <code>bin</code> folder with the Axolotl-PM versions. It doesn’t touch your worlds, plugins, player data or configuration files.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>The installer deletes any folder named <code>src</code> in the server folder. Move it somewhere else first if you keep your own files there.</p></div><h3 id="using-docker" tabindex="-1">Using Docker <a class="header-anchor" href="#using-docker" aria-label="Permalink to &quot;Using Docker&quot;">​</a></h3><p>Change the image to <code>ghcr.io/axolotl-pm/pocketmine-mp</code> and keep the rest of your setup. The Axolotl-PM image uses the same <code>/data</code> and <code>/plugins</code> volumes, the same user ID (1000), and the same <code>POCKETMINE_PLUGINS</code> and <code>POCKETMINE_ARGS</code> environment variables as the PMMP image.</p><p>See <a href="/website/previews/pr-1/native-9f14c22779bf/docs/installation/docker">Using Docker</a> for the full instructions.</p><h3 id="installing-manually" tabindex="-1">Installing manually <a class="header-anchor" href="#installing-manually" aria-label="Permalink to &quot;Installing manually&quot;">​</a></h3><p>Follow <a href="/website/previews/pr-1/native-9f14c22779bf/docs/installation/installing-manually">Installing/updating manually</a>, using your existing server folder. Replace <code>PocketMine-MP.phar</code> with the one from the <a href="https://github.com/axolotl-pm/PocketMine-MP/releases/latest" target="_blank" rel="noreferrer">latest Axolotl-PM release</a>, and replace the <code>bin</code> folder with an Axolotl-PM PHP binary.</p><p>The file name stays <code>PocketMine-MP.phar</code>, so your start scripts keep working.</p><h2 id="after-switching" tabindex="-1">After switching <a class="header-anchor" href="#after-switching" aria-label="Permalink to &quot;After switching&quot;">​</a></h2><ol><li>Update the <code>host</code> settings in <code>pocketmine.yml</code> as described in <a href="#configuration">Configuration</a>.</li><li>If you want to use NetherNet, add the <code>transport</code> section and open the required ports as described in <a href="#nethernet">NetherNet</a>.</li><li>Start the server and check the console for plugins that fail to load.</li><li>If you use plugins that depend on the network API, check whether their authors have released an update.</li></ol><h2 id="for-plugin-developers" tabindex="-1">For plugin developers <a class="header-anchor" href="#for-plugin-developers" aria-label="Permalink to &quot;For plugin developers&quot;">​</a></h2><p>Axolotl-PM is published on Packagist as <code>axolotl-pm/pocketmine-mp</code>. It declares that it replaces <code>pocketmine/pocketmine-mp</code>, so you can swap the dependency in your <code>composer.json</code> for tools like PHPStan.</p><p>Everything that changed since PMMP 5.44.3 is listed in the <a href="https://github.com/axolotl-pm/PocketMine-MP/tree/stable/changelogs" target="_blank" rel="noreferrer">changelogs</a>.</p>`,45)])])}const k=a(o,[["render",n]]);export{g as __pageData,k as default};
